-- Entries already represented in the catalog keep their existing IDs.
ALTER TABLE curriculum_topics DROP CONSTRAINT curriculum_topics_category_check;
ALTER TABLE curriculum_topics ADD CONSTRAINT curriculum_topics_category_check
  CHECK (category IN ('Grammar','Vocabulary','Functions','Discourse','Reading','Writing','Listening','Speaking','Topics'));

